"""OccBin simulation options against Dynare 7.2 (references: reference/occ_*.mat, regenerated by
reference/r_occbin_options.m). Every case compares the piecewise and linear paths (rtol 1e-10),
the regime histories exactly and the error flag (310-313) of Dynare."""
import os
import shutil
from pathlib import Path

import numpy as np
import pytest
from scipy.io import loadmat

import pydyn
from pydyn.occbin import OccbinError

ROOT = Path(__file__).resolve().parent.parent
REF = Path(os.environ.get("PYDYN_REF", str(ROOT / "reference")))


def load_model(name, tmp_path):
    shutil.copy(REF / f"{name}.mod", tmp_path)
    return pydyn.Model(pydyn.run_preprocessor(tmp_path / f"{name}.mod"))


def ref(name):
    return loadmat(REF / f"{name}.mat", squeeze_me=True)


def to_list(x):
    return [int(v) for v in np.atleast_1d(x).ravel()]


def ref_regimes(r, key, k):
    """Dynare's regime history as [[(regime, start) per constraint] per shock period]."""
    a = np.asarray(r[key], dtype=object)
    a = a.reshape(2 * k, -1)
    return [[(to_list(a[2 * j, t]), to_list(a[2 * j + 1, t])) for j in range(k)] for t in range(a.shape[1])]


def run(ob, flag_expected, shocks, **kw):
    """Python result, or the error flag if OccbinError is raised."""
    try:
        return ob.simulate(shocks, **kw)
    except OccbinError as e:
        assert e.error_flag == flag_expected, (e.error_flag, str(e))
        return e.error_flag


def check_case(ob, r, name, shocks, k=1, **kw):
    """Compare one stored variant: error flag, paths, regime history."""
    flag = int(r[f"{name}_flag"])
    res = run(ob, flag, shocks, **kw)
    if flag != 0:
        assert res == flag
        return None
    assert not isinstance(res, int), f"{name}: Dynare succeeded, pydyn raised {res}"
    np.testing.assert_allclose(res.piecewise, r[f"{name}_piecewise"], rtol=1e-10, atol=1e-12)
    np.testing.assert_allclose(res.linear, r[f"{name}_linear"], rtol=1e-10, atol=1e-12)
    assert res.regime_history == ref_regimes(r, f"{name}_regime", k), name
    return res


def check_sweep(ob, r, name, shocks, **kw):
    """Error flag of every maxit in the sweep, and the paths at the first and last success."""
    maxits = np.atleast_1d(r[f"{name}_maxits"]).astype(int)
    flags = np.atleast_1d(r[f"{name}_flags"]).astype(int)
    got = []
    paths = {}
    for mi, fl in zip(maxits, flags):
        try:
            res = ob.simulate(shocks, maxit=int(mi), **kw)
            got.append(0)
            paths[int(mi)] = res.piecewise
        except OccbinError as e:
            got.append(e.error_flag)
    assert got == flags.tolist(), (name, got, flags.tolist())
    if f"{name}_first_maxit" in r:
        np.testing.assert_allclose(paths[int(r[f"{name}_first_maxit"])], r[f"{name}_first_piecewise"], rtol=1e-10, atol=1e-12)
    if f"{name}_last_piecewise" in r:
        np.testing.assert_allclose(paths[int(maxits[-1])], r[f"{name}_last_piecewise"], rtol=1e-10, atol=1e-12)
    else:
        assert flags[-1] != 0
    return flags


# ======================================================================== one constraint, two shocks
@pytest.fixture(scope="module")
def bc(tmp_path_factory):
    m = load_model("occ_borrcon", tmp_path_factory.mktemp("bc"))
    return pydyn.Occbin(m), ref("occ_borrcon"), m


def S_of(r):
    return np.asarray(r["S"], float)


def test_borrcon_default_and_params(bc):
    ob, r, m = bc
    assert np.max(np.abs(ob.simulate(S_of(r), periods=80).piecewise - ob.simulate(S_of(r), periods=80).linear)) > 1e-2
    res = check_case(ob, r, "default", S_of(r), periods=80)
    np.testing.assert_allclose(res.ys, r["ys"], rtol=1e-12)
    # the reference ran with the same parameters
    np.testing.assert_allclose(m.params, r["params"], rtol=1e-14)


def test_borrcon_maxit_sweep_and_truncation(bc):
    ob, r, _ = bc
    flags = check_sweep(ob, r, "sw_default", S_of(r), periods=80)
    assert flags[0] == 0 and (flags[1:13] == 311).all() and flags[-1] == 0   # maxit=1 accepts the first guess
    check_case(ob, r, "maxit1", S_of(r), periods=80, maxit=1)
    # maxit=1 is not converged: the path differs from the converged one
    assert np.max(np.abs(r["maxit1_piecewise"] - r["default_piecewise"])) > 1e-3


def test_borrcon_curb_retrench(bc):
    ob, r, _ = bc
    check_case(ob, r, "curb", S_of(r), periods=80, curb_retrench=True)
    check_sweep(ob, r, "sw_curb", S_of(r), periods=80, curb_retrench=True)


def test_borrcon_endo_init(bc):
    ob, r, _ = bc
    init = np.asarray(r["init"], float)
    check_case(ob, r, "endo_init", S_of(r), periods=80, init=init)
    assert np.max(np.abs(r["endo_init_piecewise"] - r["default_piecewise"])) > 1e-3     # the option matters
    # linear path starts from the same deviations (declaration order)
    check_case(ob, r, "endo_init_noshock", np.zeros((1, 2)), periods=80, init=init)
    # in declaration order: b is the first variable, y the fifth
    assert ob.model.endo_names[0] == "b" and ob.model.endo_names[4] == "y"


def test_borrcon_exo_pos(bc):
    ob, r, _ = bc
    S = S_of(r)
    check_case(ob, r, "exo_v_only", S[:, [1]], periods=80, exo_pos=[1])
    res = check_case(ob, r, "exo_swapped", S[:, [1, 0]], periods=80, exo_pos=[1, 0])
    names = check_case(ob, r, "exo_swapped", S[:, [1, 0]], periods=80, exo_pos=["v", "u"])
    np.testing.assert_array_equal(res.piecewise, names.piecewise)
    # swapping both the columns and exo_pos reproduces the default path
    np.testing.assert_allclose(res.piecewise, r["default_piecewise"], rtol=1e-10, atol=1e-12)
    assert res.exo_pos == (1, 0)
    with pytest.raises(ValueError):
        ob.simulate(S, exo_pos=[1])


def test_borrcon_max_check_ahead(bc):
    ob, r, _ = bc
    S = S_of(r)
    check_case(ob, r, "maxcheck8", S, periods=80, check_ahead_periods=8, max_check_ahead_periods=8)
    assert np.max(np.abs(r["maxcheck8_piecewise"] - r["default_piecewise"])) > 1e-2      # the option matters
    check_sweep(ob, r, "sw_maxcheck8", S, periods=80, check_ahead_periods=8, max_check_ahead_periods=8)
    check_case(ob, r, "maxcheck20_check10", S, periods=80, check_ahead_periods=10, max_check_ahead_periods=20)
    check_sweep(ob, r, "sw_maxcheck20_check10", S, periods=80, check_ahead_periods=10, max_check_ahead_periods=20)
    check_case(ob, r, "maxcheck8_check5", S, periods=80, check_ahead_periods=5, max_check_ahead_periods=8)
    # check-ahead too short but not capped: the horizon grows endogenously, the path is the default one
    check_case(ob, r, "check12", S, periods=80, check_ahead_periods=12)
    check_sweep(ob, r, "sw_check12", S, periods=80, check_ahead_periods=12)
    np.testing.assert_allclose(r["check12_piecewise"], r["default_piecewise"], rtol=1e-10, atol=1e-12)


def test_borrcon_reset_options(bc):
    ob, r, _ = bc
    S = S_of(r)
    check_case(ob, r, "reset_regime", S, periods=80, reset_regime_in_new_period=True)
    f_reset = check_sweep(ob, r, "sw_reset_regime", S, periods=80, reset_regime_in_new_period=True)
    f_def = np.atleast_1d(r["sw_default"]) if False else np.atleast_1d(r["sw_default_flags"])
    assert not np.array_equal(f_reset, f_def)             # the option changes the number of iterations needed
    kw = dict(periods=80, check_ahead_periods=12, reset_regime_in_new_period=True, reset_check_ahead_periods_in_new_period=True)
    check_case(ob, r, "reset_both_check12", S, **kw)
    check_sweep(ob, r, "sw_reset_both_check12", S, **kw)
    # reset_check_ahead_periods without reset_regime does nothing
    check_case(ob, r, "reset_check_only_check12", S, periods=80, check_ahead_periods=12,
               reset_check_ahead_periods_in_new_period=True)


def test_borrcon_init_regime_and_indicator(bc):
    ob, r, _ = bc
    S = S_of(r)
    default = ob.simulate(S, periods=80)
    rh = default.regime_history
    # without a guess maxit=3 fails (311); the converged history as a guess succeeds
    check_case(ob, r, "maxit3", S, periods=80, maxit=3)
    check_case(ob, r, "maxit3_guess_full", S, periods=80, maxit=3, init_regime=rh)
    np.testing.assert_allclose(r["maxit3_guess_full_piecewise"], r["default_piecewise"], rtol=1e-10, atol=1e-12)
    # a guess with half-length spells needs fewer iterations than none
    half = [[(list(reg), [s[0]] + [int(np.ceil(s[1] / 2))] + s[2:]) if len(reg) > 1 else (list(reg), list(s))
             for reg, s in per] for per in rh]
    check_case(ob, r, "maxit8_guess_half", S, periods=80, maxit=8, init_regime=half)
    check_case(ob, r, "maxit8", S, periods=80, maxit=8)
    f_half = check_sweep(ob, r, "sw_guess_half", S, periods=80, init_regime=half)
    assert f_half.tolist() != np.atleast_1d(r["sw_default_flags"]).tolist()
    check_sweep(ob, r, "sw_guess_two", S, periods=80, init_regime=rh[:2])
    # a guess that ends in the binding regime, and a guess that is longer than the check-ahead rows
    g = [list(p) for p in rh]
    g[0] = [([0, 1], [1, 5])]
    check_case(ob, r, "guess_binding_end", S, periods=80, init_regime=g)
    g = [list(p) for p in rh]
    g[0] = [([1, 0], [1, 300])]
    check_case(ob, r, "guess_long", S, periods=80, init_regime=g)       # error 312
    # init_binding_indicator
    bi = np.asarray(r["bi12"], bool)
    check_case(ob, r, "maxit3_bi12", S, periods=80, maxit=3, init_binding_indicator=bi)
    check_sweep(ob, r, "sw_bi12", S, periods=80, init_binding_indicator=bi)
    with pytest.raises(ValueError):
        ob.simulate(S, periods=80, init_binding_indicator=np.zeros(250, bool))


def test_borrcon_error_codes_are_distinguishable(bc):
    ob, r, _ = bc
    S = S_of(r)
    with pytest.raises(OccbinError) as e:
        ob.simulate(S, periods=80, maxit=3)
    assert e.value.error_flag == 311 and e.value.period == 1
    assert isinstance(e.value, pydyn.occbin.OccbinMaxitError)
    g = [[([1, 0], [1, 300])]]
    with pytest.raises(OccbinError) as e:
        ob.simulate(S, periods=80, init_regime=g)
    assert e.value.error_flag == 312 and isinstance(e.value, pydyn.occbin.OccbinHorizonError)


def test_borrcon_options_from_mod(tmp_path):
    m = load_model("occ_borrcon_opts", tmp_path)
    ob = pydyn.Occbin(m)
    r = ref("occ_borrcon_opts")
    o = ob.mod_options()
    maxit, curb, check, maxcheck, reset, reset_check, periods = [float(v) for v in r["mod_opts"]]
    assert o == dict(maxit=int(maxit), curb_retrench=bool(curb), check_ahead_periods=int(check),
                     max_check_ahead_periods=int(maxcheck), reset_regime_in_new_period=bool(reset),
                     reset_check_ahead_periods_in_new_period=bool(reset_check), periods=int(periods))
    assert curb and reset and reset_check
    res = ob.run()
    np.testing.assert_allclose(res.piecewise, r["mod_piecewise"], rtol=1e-10, atol=1e-12)
    np.testing.assert_allclose(res.linear, r["mod_linear"], rtol=1e-10, atol=1e-12)
    assert res.regime_history == ref_regimes(r, "mod_regime", 1)
    # the options matter: ignoring them gives another path
    plain = ob.simulate(ob.surprise_shocks(), periods=80)
    assert np.max(np.abs(plain.piecewise - res.piecewise)) > 1e-3


# ======================================================================== two constraints, cycling guesses
PSETS = {   # (psi, phi, rho) and shocks, as in reference/r_occbin_options.m
    "c1": ((10.30721957177062, 0.9879452800064452, 0.7469193213904868),
           [0.17885813149410787, -0.18518412993264557, 0.09168812685568793]),
    "c3": ((4.6525347234318675, 0.950930792986048, 0.5850521699901848),
           [0.03831108818687395, 0.08817287153074853, -0.0932996254397529]),
    "c4": ((13.436741484971341, 0.9608110490106523, 0.5495106530269722),
           [0.1246837534942502, 0.037652096093670165, -0.3040040918655403]),
    "e1": ((4.038590202884413, 0.9538230658935829, 0.5028849753522318),
           [0.278665132869575, -0.4631084100053847, -0.09791875946873171]),
}
VARIANTS = {
    "default": {},
    "per": dict(periodic_solution=True),
    "per_loose": dict(periodic_solution=True, periodic_solution_strict=False),
    "per_loose_thr0": dict(periodic_solution=True, periodic_solution_strict=False, periodic_solution_threshold=0),
    "per_loose_thr3": dict(periodic_solution=True, periodic_solution_strict=False, periodic_solution_threshold=3),
    "loose_only": dict(periodic_solution_strict=False),
    "per_thr0": dict(periodic_solution=True, periodic_solution_threshold=0),
    "curb": dict(curb_retrench=True),
    "curb_per": dict(curb_retrench=True, periodic_solution=True),
    "curb_per_loose": dict(curb_retrench=True, periodic_solution=True, periodic_solution_strict=False),
    "maxit3": dict(maxit=3),
    "maxit2_per": dict(maxit=2, periodic_solution=True),
    "maxit1": dict(maxit=1),
}


@pytest.fixture(scope="module")
def rbc(tmp_path_factory):
    m = load_model("occ_rbc_cyc", tmp_path_factory.mktemp("rbc"))
    return m, ref("occ_rbc_cyc")


def rbc_occbin(m, pset):
    for nm, v in zip(("psi", "phi", "rho"), PSETS[pset][0]):
        m.set_param(nm, v)
    return pydyn.Occbin(m)


@pytest.mark.parametrize("pset", list(PSETS))
@pytest.mark.parametrize("variant", list(VARIANTS))
def test_rbc_periodic_variants(rbc, pset, variant):
    m, r = rbc
    ob = rbc_occbin(m, pset)
    S = np.asarray(PSETS[pset][1]).reshape(-1, 1)
    np.testing.assert_array_equal(S.ravel(), np.atleast_1d(r[f"{pset}_S"]))
    check_case(ob, r, f"{pset}_{variant}", S, k=2, periods=80, **VARIANTS[variant])


@pytest.mark.parametrize("pset", list(PSETS))
def test_rbc_maxit_sweeps(rbc, pset):
    m, r = rbc
    ob = rbc_occbin(m, pset)
    S = np.asarray(PSETS[pset][1]).reshape(-1, 1)
    check_sweep(ob, r, f"{pset}_sw_loose_only", S, periods=80, periodic_solution_strict=False)
    check_sweep(ob, r, f"{pset}_sw_per_loose", S, periods=80, periodic_solution=True, periodic_solution_strict=False)


def test_rbc_error_flags_cover_310_to_313(rbc):
    """Dynare's flags in the references: every code occurs, and pydyn reproduces each one."""
    m, r = rbc
    seen = {int(v) for k, v in r.items() if k.endswith("_flag") and not isinstance(v, np.ndarray)}
    assert {0, 310, 311, 313} <= seen
    for pset in PSETS:
        ob = rbc_occbin(m, pset)
        S = np.asarray(PSETS[pset][1]).reshape(-1, 1)
        flags = {}
        for v, kw in VARIANTS.items():
            try:
                ob.simulate(S, periods=80, **kw)
                flags[v] = 0
            except OccbinError as e:
                flags[v] = e.error_flag
                assert type(e).error_flag == e.error_flag
                assert 1 <= e.period <= len(S)       # 1-based shock period that failed
        assert flags == {v: int(r[f"{pset}_{v}_flag"]) for v in VARIANTS}
    # 310: strict periodic and periodic_solution off; 313: longer loop; 311: maxit; each a different class
    assert issubclass(pydyn.occbin.OccbinPeriodicError, OccbinError) and pydyn.occbin.OccbinPeriodicError.error_flag == 310
    assert pydyn.occbin.OccbinLoopError.error_flag == 313 and pydyn.occbin.OccbinHorizonError.error_flag == 312


def test_rbc_periodic_solution_selects_a_guess(rbc):
    m, r = rbc
    ob = rbc_occbin(m, "c1")
    S = np.asarray(PSETS["c1"][1]).reshape(-1, 1)
    res = ob.simulate(S, periods=80, periodic_solution=True)
    assert res.periodic == [False, True, False]            # selected in the second shock period
    d = res.diagnostics[1]
    assert d["selected"] is not None and not d["violates"][d["selected"] - 1]
    lin = res.linear
    assert np.max(np.abs(res.piecewise - lin)) > 1e-2      # the path is a real piecewise solution


def test_rbc_options_from_mod(tmp_path):
    m = load_model("occ_rbc_cyc", tmp_path)
    ob = pydyn.Occbin(m)
    r = ref("occ_rbc_cyc")
    maxit, per, thr, strict, periods = [float(v) for v in r["mod_opts"]]
    assert ob.mod_options() == dict(periods=int(periods), maxit=int(maxit), periodic_solution=bool(per),
                                    periodic_solution_threshold=int(thr), periodic_solution_strict=bool(strict))
    assert per and not strict and thr == 3
    res = ob.run()
    np.testing.assert_allclose(res.piecewise, r["mod_piecewise"], rtol=1e-10, atol=1e-12)
    np.testing.assert_allclose(res.linear, r["mod_linear"], rtol=1e-10, atol=1e-12)
    assert res.regime_history == ref_regimes(r, "mod_regime", 2)
    assert res.periodic == [False, False, True]
    # without the options the same shocks fail (313)
    with pytest.raises(OccbinError) as e:
        ob.run(periodic_solution=False, periodic_solution_strict=True)
    assert e.value.error_flag == 313


def test_error_bind_error_relax(tmp_path, rbc):
    """The periodic solution picks the guess with the smallest constraint error; error_bind and
    error_relax of the occbin_constraints block change that choice (Dynare: occbin_difference.m)."""
    m = load_model("occ_rbc_err", tmp_path)
    cons = {c["name"]: c for c in m.occbin_constraints}
    assert cons["INEG"]["error_bind"] and cons["IRR"]["error_relax"] and not cons["IRR"]["error_bind"]
    ob = pydyn.Occbin(m)
    r = ref("occ_rbc_err")
    S = np.asarray(r["S"], float).reshape(-1, 1)
    for name, kw in (("default", {}), ("per", dict(periodic_solution=True)),
                     ("per_loose", dict(periodic_solution=True, periodic_solution_strict=False)),
                     ("per_thr0", dict(periodic_solution=True, periodic_solution_threshold=0))):
        check_case(ob, r, name, S, k=2, periods=80, **kw)
    res = check_case(ob, r, "mod", S, k=2, periods=80, periodic_solution=True)
    assert res.diagnostics[2]["selected"] == 2 and res.diagnostics[2]["violates"].all()   # both guesses violate: the error decides
    # the default errors (reference run with the same parameters and shocks, no error_* expressions) pick the other guess
    m2, r2 = rbc
    ob2 = rbc_occbin(m2, "e1")
    res2 = ob2.simulate(S, periods=80, periodic_solution=True)
    assert res2.diagnostics[2]["selected"] == 1
    assert res2.regime_history != res.regime_history
    np.testing.assert_allclose(res2.piecewise, r2["e1_per_piecewise"], rtol=1e-10, atol=1e-12)
    assert np.max(np.abs(res.piecewise - res2.piecewise)) > 1e-5
    # errors as the preprocessor defines them: abs(lhs - rhs) of bind / relax, or the given expressions
    z = np.zeros((2, ob.n)) + ob.ys
    b, rl, eb, er = ob.check(z)
    assert eb.shape == (2, 2)
    # INEG at the steady state (log_Invest - log(ss) = 0): default error abs(0 - (-1e-6)) = 1e-6; custom 1000*abs(0) = 0
    assert np.allclose(ob2.check(z)[2][:, 1], 1e-6) and np.allclose(eb[:, 1], 0.0)
    assert np.allclose(ob.check(z)[3][:, 0], 1.0)              # IRR error_relax = 1 + abs(Lambda) = 1 at the steady state
    assert np.allclose(ob2.check(z)[3][:, 0], 0.0)             # default: abs(Lambda - 0)


# ======================================================================== IRFs
def irf_arrays(r, prefix, exo, sign):
    return r[f"{prefix}_{exo}_{sign}_piecewise"], r[f"{prefix}_{exo}_{sign}_linear"]


def test_irf_occbin_borrcon_defaults(bc):
    ob, r, m = bc
    out = ob.irf_occbin()            # Dynare defaults: stderr-sized shocks, both signs, 40 periods
    assert set(out) == {(e, s) for e in ("u", "v") for s in ("pos", "neg")}
    for (exo, sign), d in out.items():
        pw, lin = irf_arrays(r, "irf_default", exo, sign)
        assert pw.shape == (41, 8)
        np.testing.assert_allclose(d["piecewise"], pw, rtol=1e-10, atol=1e-12)
        np.testing.assert_allclose(d["linear"], lin, rtol=1e-10, atol=1e-12)
    # a state-dependent piece: the positive u shock hits the constraint, the negative one does not
    pw, lin = irf_arrays(r, "irf_default", "u", "pos")
    assert np.max(np.abs(pw - lin)) > 1e-3
    pw, lin = irf_arrays(r, "irf_default", "u", "neg")
    assert np.max(np.abs(pw - lin)) < 1e-12
    assert int(r["irf_stale_exo_pos_error"]) == 1     # Dynare quirk, see the report


def test_irf_occbin_borrcon_options(bc):
    ob, r, _ = bc
    out = ob.irf_occbin(periods=30, shocksize=[0.3, 0.1], check_ahead_periods=12, maxit=25)
    for (exo, sign), d in out.items():
        pw, lin = irf_arrays(r, "irf_big", exo, sign)
        assert pw.shape == (31, 8)
        np.testing.assert_allclose(d["piecewise"], pw, rtol=1e-10, atol=1e-12)
        np.testing.assert_allclose(d["linear"], lin, rtol=1e-10, atol=1e-12)
    out1 = ob.irf_occbin(periods=30, shocksize=0.3, exo_names=["u"], shocksigns=("pos",), check_ahead_periods=12, maxit=25)
    assert list(out1) == [("u", "pos")]
    np.testing.assert_allclose(out1[("u", "pos")]["piecewise"], r["irf_big_u_pos_piecewise"], rtol=1e-10, atol=1e-12)


def test_existing_irf_method_matches_dynare(bc):
    """Occbin.irf (impulse minus baseline) gives Dynare's response; it returns `periods` rows, Dynare periods+1."""
    ob, r, m = bc
    size = float(np.sqrt(m.Sigma_e[0, 0]))
    for sign, sg in (("pos", 1.0), ("neg", -1.0)):
        got = ob.irf([sg * size, 0.0], periods=41, check_ahead_periods=30)
        np.testing.assert_allclose(got, r[f"irf_default_u_{sign}_piecewise"], rtol=1e-10, atol=1e-12)
    got = ob.irf([0.0, 0.1], periods=31, check_ahead_periods=12, maxit=25)
    np.testing.assert_allclose(got, r["irf_big_v_pos_piecewise"], rtol=1e-10, atol=1e-12)


def test_irf_occbin_rbc_two_constraints(rbc):
    m, r = rbc
    for nm, v in zip(("psi", "phi", "rho"), (5.0, 0.975, 0.9)):
        m.set_param(nm, v)
    ob = pydyn.Occbin(m)
    out = ob.irf_occbin(periods=40, shocksize=0.04, check_ahead_periods=200)
    for (exo, sign), d in out.items():
        pw, lin = irf_arrays(r, "irf", exo, sign)
        assert pw.shape == (41, 8)
        np.testing.assert_allclose(d["piecewise"], pw, rtol=1e-10, atol=1e-12)
        np.testing.assert_allclose(d["linear"], lin, rtol=1e-10, atol=1e-12)
    assert np.max(np.abs(irf_arrays(r, "irf", "epsilon", "neg")[0] - irf_arrays(r, "irf", "epsilon", "neg")[1])) > 1e-3
    # default size (stderr 0.015) and the default check-ahead of 30 fail for this model (311), as in Dynare
    with pytest.raises(OccbinError) as e:
        ob.irf_occbin()
    assert e.value.error_flag == 311
    out = ob.irf_occbin(periods=40, check_ahead_periods=200)
    for (exo, sign), d in out.items():
        np.testing.assert_allclose(d["piecewise"], irf_arrays(r, "irf_dflt", exo, sign)[0], rtol=1e-10, atol=1e-12)


