PSETS1 = {'a': ((8.20453071654218, 0.43376653874397436, 4.162224515697595), [-0.006401074156627856, 0.21600250881228591, -0.1255342530145265]), 'b': ((29.06953055729189, 0.3407807947098334, 0.7619883020628548), [-0.06332487508731809, -0.06344217665694422]), 'c': ((1.5460870251082188, 0.4426697608503545, 1.5078256168794189), [0.060713476541191136])}
V1 = ["default", "per", "per_loose", "per_loose_thr0", "loose_only", "curb", "curb_per", "maxit3"]


@pytest.mark.parametrize("pset", list(PSETS1))
@pytest.mark.parametrize("variant", V1)
def test_one_constraint_periodic_variants(tmp_path_factory, pset, variant):
    m = load_model("occ_rbc1", tmp_path_factory.mktemp("rbc1"))
    r = ref("occ_rbc1")
